  "srRejection": "Rejet (offre)",
  "srHowTitle": "Comment les repérer",
  "srHowBody": "Le support est un niveau où le prix cesse de baisser et rebondit : la demande dépasse l'offre.\nLa résistance est un niveau où le prix cesse de monter et se retourne : l'offre dépasse la demande.\nPlus un niveau accumule de rebonds ou de rejets, plus il est fiable.\nSi le prix casse le niveau avec force et volume, support et résistance échangent leur rôle.",
  "srUseTitle": "Usage pratique",
  "srUseBody": "Chercher des achats près du support, avec le stop juste en dessous.\nPrendre des bénéfices ou vendre près de la résistance.\nTrader la cassure seulement une fois confirmée, idéalement au retest du niveau.",
