  "tweezersBottomName": "Tweezer Bottom (pinces)",
  "tweezersBottomDesc": "Deux bougies consécutives aux plus bas identiques. Signe d'un fort support et d'un intérêt acheteur à ce niveau de prix.",
  "tweezersTopName": "Tweezer Top (pinces)",
  "tweezersTopDesc": "Deux bougies consécutives aux plus hauts identiques. Signe d'une forte résistance et d'un intérêt vendeur à ce niveau de prix.",
  "evTitle": "Trading fondé sur les preuves",
  "evIntro": "Qu'est-ce qui est PROUVÉ par les données, et non par des promesses ? Nous réunissons ici ce que montrent les études académiques, les régulateurs et un siècle de données de fonds, banques et desks de trading : combien perdent vraiment, quelles stratégies ont survécu à des décennies de statistiques, et comment les professionnels gèrent le risque. Le fil conducteur est la loi des grands nombres : un trade, c'est du hasard ; mille trades, c'est de la statistique.",
  "hzTitle": "Horaires et saisonnalité",
  "hzIntro": "À certaines heures et dates, le marché A TENDANCE à se comporter de façon similaire, poussé par les flux d'argent (ouvertures, données, clôtures, échéances). Ce ne sont pas des règles fixes ni des signaux d'achat : ce sont des tendances statistiques qui t'aident à choisir QUAND trader et quand t'écarter. Toutes les heures en heure de Francfort (UTC+2) (elles bougent de ±1 h avec l'heure d'été).",
  "msTitle": "Structure de marché",
  "msIntro": "Avant toute figure, le prix est une séquence de sommets et de creux. Lire la STRUCTURE — si ces sommets et creux montent, descendent ou vont de côté — indique la tendance et qui commande. C'est la base sur laquelle reposent les figures chartistes, le SMC et presque tout le reste. Ici tu apprends à la lire et à repérer quand elle change.",
  "mcTitle": "Macro : cycle, taux et rotation",
  "mcIntro": "Le contexte macro fait bouger des marchés entiers — plus que n'importe quel graphique isolé. Les taux d'intérêt, l'inflation et la croissance fixent la marée qui soulève ou coule tous les bateaux. Il ne s'agit pas de le prédire mais de se positionner : savoir dans quelle phase du cycle on est et ce qui y fonctionne d'ordinaire.",
  "cvTitle": "Valoriser une entreprise en profondeur",
  "cvIntro": "L'analyse fondamentale cherche ce qu'une entreprise vaut vraiment et le compare à son prix en bourse. Prix ≠ valeur : une excellente entreprise peut être un mauvais placement si tu surpaies, et une médiocre une aubaine. Ici tu apprends à lire ses chiffres et à estimer sa valeur, au-delà des 4 ratios de base.",
  "ofTitle": "Order flow / lecture de la bande",
  "ofIntro": "Le prix est le résultat ; l'order flow est la cause. Ici tu apprends à lire la vraie pression acheteuse et vendeuse — qui est agressif, où se trouve la liquidité, où elle est absorbée — au lieu de la seule bougie terminée. Il faut des données niveau 2 et de la pratique, mais c'est le prisme des day traders professionnels.",
  "protoTitle": "Protocole avant de trader",
  "protoIntro": "Trois outils pour transformer la discipline en règles concrètes : tes coupe-circuits, un filtre d'entrée et un check mental. Utilise-les dans cet ordre avant chaque séance et chaque trade.",
  "brkTitle": "Règles d'arrêt (coupe-circuits)",
  "brkIntro": "Décide à l'avance combien tu peux perdre avant de fermer la plateforme. Quand une limite se déclenche, c'est fini pour la journée : pas d'exception, pas de 'encore un'.",
