  "pckTitle": "Checklist avant trade",
  "pckIntro": "Avant de cliquer 'acheter', coche ce qui est vrai. Plus de cases, meilleur le trade ; s'il en reste beaucoup de vides, saute — il y en aura toujours un autre.",
