  "structLogClear": "Effacer",
  "structLogNote": "Le scanner mémorise ce qu'il détecte sur cet actif (ruptures de structure et signaux de bougies) et le conserve ici même après un rechargement. Les éléments en bleu ont été vus pour la première fois lors des dernières 24 h.",
