  "nasdaqMode": "Nasdaq",
  "ideskTitle": "La table de trading institutionnelle",
  "ideskIntro": "Une banque ou un fonds ne «trade» pas comme le retail : le travail est réparti entre spécialistes, avec des processus, des limites et de la technologie. Voici comment fonctionne une table pro de l'intérieur et ce que tu peux voler à chaque rôle pour trader en pro, même seul chez toi.",
  "discTitle": "Discipline et performance professionnelle",
  "discIntro": "Ce qui sépare le pro rentable du retail qui explose son compte, ce n'est pas l'indicateur secret : c'est la façon de gérer son mental, ses erreurs et son stress sous pression. C'est le «logiciel» du trader d'élite, emprunté aux tables institutionnelles, aux pilotes, aux chirurgiens et aux sportifs de haut niveau.",
  "mstTitle": "Stress test de marge",
  "mstIntro": "Avant d'ouvrir une position à effet de levier, vérifie si tu survis à une forte baisse. Saisis ton solde et tes positions et vois, scénario par scénario, combien tu perds, ce qu'il te reste et si tu déclenches un appel de marge ou une liquidation. La question clé : « est-ce que je survis à −20 % ? ».",
  "mstAccount": "Solde du compte",
  "mstMaintRate": "Marge de maintenance",
  "mstPosition": "Position",
  "mstLong": "Long",
  "mstShort": "Short",
  "mstAddPosition": "Ajouter une position",
  "mstGross": "Exposition brute",
  "mstNet": "Exposition nette",
  "mstLeverage": "Levier",
  "mstNeutral": "Portefeuille neutre (les longs et les shorts se compensent) : aucun mouvement purement directionnel ne déclenche la liquidation. Attention au risque de base.",
  "mstLiqLabel": "Tu es liquidé sur un mouvement de marché de",
  "mstLiqSub": "appliqué à ton exposition nette (négatif = baisse ; positif = hausse)",
  "mstScenariosTitle": "Scénarios de marché",
  "mstColMove": "Mouvement",
  "mstColPnl": "P&L",
  "mstColEquity": "Solde après le choc",
  "mstColStatus": "Statut",
  "mstOk": "Tient",
  "mstCall": "Appel de marge",
  "mstLiq": "Liquidé",
  "mstCustom": "Scénario personnalisé",
  "mstNote": "Modèle simplifié : un vrai courtier compense par produit et applique une marge de maintenance différente selon l'actif (crypto ~0,5 %, CFD indices/forex plus élevée). Sers-t'en pour l'ORDRE DE GRANDEUR du risque, pas comme chiffre exact de ton courtier. Leçon : plus de levier, plus la liquidation est proche d'un mouvement de marché normal.",
  "edgeUseJournal": "Utiliser mes données du journal",
  "edgeLoaded": "Chargé depuis {n} trades réels de ton journal",
  "edgeNoData": "Tu n'as pas encore de trades clôturés dans le journal. Enregistres-en et reviens.",
  "edgeNotLogged": "Connecte-toi et enregistre des trades dans le journal pour utiliser tes données réelles.",
  "edgeSampleWarn": "petit échantillon, fiabilité limitée (idéalement ≥100 trades)",
  "tvSearchAsset": "Rechercher un actif…",
  "alertSymbolPh": "BTC, AAPL…",
  "ddrTitle": "Drawdown et récupération",
  "ddrIntro": "La mathématique du drawdown est asymétrique et cruelle : perdre 50% exige de gagner 100% juste pour revenir à l'équilibre. Cette calculatrice montre combien vous devez récupérer et combien de trades cela prendra avec votre expectancy actuelle — la raison pour laquelle les fonds professionnels réduisent la taille dès que le drawdown dépasse leur limite (typiquement 10-20%).",
  "ddrDrawdown": "Drawdown actuel",
  "ddrExpectancy": "Expectancy par trade",
  "ddrRequired": "Gain nécessaire pour récupérer",
  "ddrRequiredSub": "sur le capital restant, juste pour revenir au break-even",
  "ddrTrades": "Trades estimés",
  "ddrTradesSub": "avec votre risque et expectancy actuels, en composé (∞ = sans edge on ne récupère jamais)",
  "ddrTableTitle": "Table : perte → gain nécessaire",
  "ddrColDd": "Drawdown",
  "ddrColReq": "Récupération nécessaire",
  "ddrNote": "Politique institutionnelle : les fonds définissent un drawdown maximal acceptable (ex. 15-20%) et des règles automatiques — à -10% la taille est réduite de moitié, à -15% on arrête de trader et on révise le système. Un VaR quotidien (valeur en risque) plafonne ce que le desk peut perdre un jour normal. Copiez l'idée : définissez VOTRE limite avant de trader, pas pendant la chute.",
  "heatCorrLabel": "Corrélation moyenne entre positions",
  "heatEffective": "Risque effectif ajusté de la corrélation",
  "heatEffectiveSub": "entre diversification totale (0%) et un seul gros trade (100%). Plusieurs paires USD ou plusieurs valeurs tech ≈ 60-90%.",
  "gkTitle": "Les grecques des options",
  "gkIntro": "Les grecques mesurent comment le prix d'une option change quand chaque variable bouge : sous-jacent, temps, volatilité et taux. C'est le tableau de bord du trader d'options — sans elles, vous volez à l'aveugle. Chaque carte inclut un exemple chiffré ; entraînez-vous ensuite avec la calculatrice Black-Scholes de la section Options.",
  "mlqTitle": "Marge et liquidation sur dérivés",
  "mlqIntro": "Si vous tradez des futures ou des perpétuels avec levier, la marge est votre survie. La plupart des comptes ne meurent pas d'une mauvaise analyse, mais de ne pas comprendre COMMENT et QUAND l'exchange vous liquide. Ce module explique les modes de marge, les modes de position, le prix de liquidation et la protection contre les mèches de manipulation.",
  "ntTitle": "Trader les news et événements",
  "ntIntro": "Les données à fort impact (NFP, IPC, taux) bougent le marché en secondes. Savoir quoi faire avant, pendant et après sépare l'opportunité du compte grillé. Utilisez le calendrier économique du Dashboard.",
  "smTitle": "Sentiment de marché",
  "smIntro": "Mesure ce que ressent la foule : peur ou cupidité. Aux extrêmes, le sentiment est un carburant contrarien — quand TOUT le monde est haussier, il ne reste plus d'acheteurs. Complète le COT de ce pilier.",
  "imTitle": "Analyse intermarché",
  "imIntro": "Aucun marché ne bouge seul (John Murphy). Dollar, obligations, matières premières et actions sont liés : lire ces relations donne le contexte macro qui confirme — ou réfute — votre trade. 15 % de l'examen CMT, ce n'est pas pour rien.",
  "bcTitle": "Ampleur, cycles et saisonnalité",
  "bcIntro": "Un indice peut monter porté par 5 méga-caps pendant que le reste coule : l'ampleur mesure la santé INTERNE du mouvement. Cycles et saisonnalité ajoutent le 'quand' statistique. Du programme CMT que presque aucun particulier ne regarde.",
  "bkrTitle": "Courtiers, régulation et arnaques",
  "bkrIntro": "Vous pouvez tout réussir sur le graphique et tout perdre en choisissant mal où déposer. Ce module vous apprend à vérifier un courtier en 10 minutes et à repérer les arnaques du secteur.",
