  "aiCoachIntro_91e0e7": "Appuyez sur {analyzeBold} et Claude Sonnet 4.5 analysera votre stratégie actuelle : points forts, risques, améliorations concrètes et verdict final. Conçu comme un coach senior en trading de volatilité.",
