  "aiCoachDisclaimer_91e0eb": "Analyse générée par IA — ne constitue pas un conseil financier. Validez toujours avec votre propre jugement.",
  "bullishBias_91e0ec": "Biais HAUSSIER : vous gagnez si {symbol} monte. Seuil de rentabilité à l'échéance ~${be}.",
  "bearishBias_91e0ed": "Biais BAISSIER : vous gagnez si {symbol} descend en dessous de ${be}.",
