  "thetaNegative_91e0f0": "Theta NÉGATIF : vous payez une prime qui se dégrade chaque jour. Le mouvement doit intervenir RAPIDEMENT avant que le temps n'érode la valeur.",
  "thetaPositive_91e0f1": "Theta POSITIF : vous encaissez de la prime. Le TEMPS JOUE EN VOTRE FAVEUR — si le prix ne bouge pas, vous gagnez du decay quotidien.",
  "thetaNeutral_91e0f2": "Theta NEUTRE : les positions longues et courtes se compensent. Le mouvement du prix importe plus que le temps.",
