  "lotUnknownSymbol": "{symbol} n'est pas au catalogue, donc nous ne connaissons ni sa taille de lot ni son pip. Choisis un autre symbole, ou dimensionne depuis le bureau de calcul, où la taille de contrat se saisit à la main.",
  "lotCrossPair": "Cette paire cote en {quote} et ton compte est en dollars. La conversion demande un troisième taux de change que nous n'avons pas ici, et des lots calculés dans la mauvaise devise valent moins que pas de lots du tout.",
  "lotFormula": "Lots = (risque en devise de cotation) / (pips × pip × unités par lot) · le pip vient du catalogue, pas d’une constante",
  "patternBlocked_incomplete": "Il manque des données : l'entrée, le stop et l'objectif sont tous nécessaires, et le stop ne peut pas être au prix d'entrée.",
  "patternBlocked_too_small": "Avec ce risque et cette distance de stop, même la plus petite position ne sort pas. Soit le stop est trop loin, soit le risque est trop court.",
  "patternCapped_margin": "Ce n'est pas ton risque qui limite la taille, c'est la marge : le compte ne finance pas la position que ce stop permettrait.",
  "patternCapped_exposure": "Ce n'est pas ton risque qui limite la taille, c'est l'exposition : cette position dépasserait le plafond de 10× le compte.",
