  "faqSubtitle_l004": "Les questions les plus courantes avant de commencer.",
  "testimonial1Quote_l010": "Je suis passé de trader à l'aveugle à avoir des métriques claires de R/R, position size et win rate. Mon compte ne subit plus de drawdowns brutaux.",
  "testimonial1Author_l011": "Carlos M.",
  "testimonial1Role_l012": "Day Trader Crypto · 4 ans",
  "testimonial2Quote_l020": "Le Strategy Optimizer et l'AI Coach m'économisent des heures d'analyse. Je rentabilise l'abonnement chaque mois avec une seule opération bien planifiée.",
  "testimonial2Author_l021": "Ana R.",
  "testimonial2Role_l022": "Swing Trader Options",
  "testimonial3Quote_l030": "Je l'utilise quotidiennement depuis 8 mois. Le Monte Carlo et le journal ont transformé ma vision du risque. 5 étoiles.",
  "testimonial3Author_l031": "David L.",
  "testimonial3Role_l032": "Trader Indépendant · Forex",
  "faqQ1_l040": "Dois-je être expert pour l'utiliser ?",
  "faqA1_l041": "Non. L'application guide pas à pas chaque calculatrice et l'Education Center couvre depuis les bases (qu'est-ce qu'un Stop Loss) jusqu'aux stratégies avancées avec options. Il y a un Demo Trader gratuit pour tout tester sans risque.",
  "faqQ2_l050": "Puis-je annuler l'abonnement quand je veux ?",
  "faqA2_l051": "Oui. Annulez en 1 clic depuis votre profil. Aucun engagement. Si vous achetez la formule Lifetime, l'accès est permanent — sans paiements récurrents.",
  "faqQ3_l060": "Quels actifs sont supportés ?",
  "faqA3_l061": "Crypto, Forex, Actions US (NYSE/NASDAQ), Indices (SPX, NDX, DAX, etc.), Matières Premières et Contrats à Terme. Les données crypto sont en temps réel ; les autres marchés peuvent être différés.",
  "faqQ4_l070": "L'IA du Trade Coach est-elle payante en plus ?",
  "faqA4_l071": "Non. L'AI Trade Coach (Claude Sonnet 4.5) est inclus dans tous les plans Premium. Il analyse votre stratégie, identifie les risques et suggère des améliorations comme un mentor senior.",
  "faqQ5_l080": "Fonctionne-t-il sur mobile ?",
  "faqA5_l081": "Oui. Design responsive complet. Les calculatrices et le dashboard fonctionnent parfaitement sur iOS/Android. Application native prévue au roadmap Q2.",
