  "trendRule5": "A closed candle OUTSIDE the trend line is a break — don't fight it",
  "trendBreakTitle": "Cassures de Lignes de Tendance",
  "trendBreakDesc": "When price decisively closes outside a trend line with strong momentum and volume, the trend may be reversing. Wait for a retest of the broken line before entering in the new direction.",
  "trendBullLine": "Bullish Trend Line",
  "trendBearLine": "Bearish Trend Line",
  "fundTab": "Fondamentaux",
  "techTab": "Technique",
  "ewTab": "Vagues d'Elliott",
  "ichiTab": "Ichimoku",
  "ichiTitle": "Ichimoku Kinko Hyo",
  "smcTitle": "Smart Money / ICT",
  "optTitle": "Stratégies d'options",
  "optIntro": "Combiner calls et puts permet de construire des positions à risque défini et de profiter non seulement de la direction, mais aussi de la volatilité et de l'érosion du temps. Utilisez la Calculatrice d'options pour voir les greeks et le diagramme de payoff de chacune.",
  "smcIntro": "L'approche 'smart money' (popularisée par ICT) tente de suivre les traces de l'argent institutionnel : où les ordres s'accumulent, comment la liquidité du particulier est chassée et où le prix revient. Elle est discrétionnaire — utilisez-la comme confluence, pas comme système magique.",
  "ichiIntro": "Un 'graphique d'équilibre en un coup d'œil' japonais, créé par Goichi Hosoda. Cinq lignes et un 'nuage' projeté montrent d'un coup la tendance, le support/résistance, le momentum et les signaux d'entrée — conçu pour lire le marché d'un seul regard. Très populaire en forex et crypto.",
  "ewTitle": "Théorie des vagues d'Elliott",
  "ewIntro": "Ralph Elliott a observé que la psychologie des foules fait évoluer les marchés selon des motifs de vagues répétitifs. Le prix progresse en une séquence 'motrice' de 5 vagues dans le sens de la tendance, puis corrige en une séquence de 3 vagues à contre-sens. La même forme 5-3 se répète à chaque degré, des minutes aux décennies.",
  "fundAnalTab": "Fondamental",
  "stylesTab": "Styles",
  "mechTab": "Mécanique",
  "volverAlDashboard": "Retour au tableau de bord",
  "fundTitle": "Fondamentaux du Trading",
  "fundIntro": "Comprendre les concepts fondamentaux du trading sur différents marchés",
  "mktForexName": "Forex",
  "mktStocksName": "Actions",
