  "strat_csp_desc": "Vendre un put en immobilisant 100% du strike en cash. Même payoff qu’un short put, capital immobilisé différent.",
  "strat_protective_put_desc": "Actions plus un put acheté en dessous : une assurance avec franchise.",
  "strat_covered_put_desc": "Actions vendues à découvert plus un put vendu. Encaisse la prime tant que le prix ne monte pas.",
  "strat_covered_strangle_desc": "Actions plus un call et un put vendus hors de la monnaie. Double prime, obligation des deux côtés.",
  "strat_ratio_call_write_desc": "Actions avec deux calls vendus : un couvert, un nu.",
  "strat_ratio_put_write_desc": "Actions vendues à découvert avec deux puts vendus : un couvert, un nu.",
  "strat_stock_repair_desc": "Sur une position en perte : un call acheté et deux vendus plus haut, pour baisser le point mort sans remettre d’argent.",
  "strat_call_calendar_desc": "Vendre le call proche et acheter le même call plus loin. Vit du fait que le temps court plus vite sur la jambe courte.",
  "strat_put_calendar_desc": "Vendre le put proche et acheter le même put à échéance plus lointaine.",
  "strat_call_diagonal_desc": "Un calendar avec strikes différents : la jambe courte plus haute ajoute un biais haussier.",
  "strat_put_diagonal_desc": "Un calendar de puts avec strikes différents : la jambe courte plus basse ajoute un biais baissier.",
  "strat_double_calendar_desc": "Deux calendars, un en puts en dessous et un en calls au-dessus. Gagne si le prix finit entre les deux.",
  "strat_double_diagonal_desc": "Double calendar avec les jambes longues plus éloignées : élargit la zone de gain contre plus de débit.",
  "strat_jelly_roll_desc": "La différence entre deux synthétiques sur le même strike à deux échéances. Son prix est purement taux et dividende.",
