  "strat_zebra_desc": "Deux calls dans la monnaie achetés contre un vendu : delta proche de 100 sans valeur extrinsèque nette.",
  "strat_risk_reversal_desc": "Finance le call acheté en vendant un put. Synthétique haussier à coût quasi nul.",
  "strat_seagull_desc": "Un risk reversal plafonné par un call vendu plus haut : structure moins chère en renonçant au dernier segment.",
  "strat_big_lizard_desc": "Un straddle vendu avec un call acheté au-dessus : supprime le risque à la hausse, ne laisse que celui à la baisse.",
  "strat_reverse_jade_desc": "Un call vendu plus un spread de puts vendu : sans risque en bas, avec risque en haut.",
  "strat_long_call_condor_desc": "Quatre calls définissant un plateau de gain entre les deux strikes centraux.",
  "strat_long_put_condor_desc": "Le même condor construit entièrement avec des puts.",
  "strat_long_put_butterfly_desc": "Un butterfly de puts : maximum au strike central, risque limité au débit.",
