  "strat_xmas_call_desc": "Un butterfly de calls asymétrique 1-3-2 : moins cher que le classique, avec la zone de gain décalée.",
  "strat_xmas_put_desc": "La version puts du butterfly 1-3-2, décalée vers le bas.",
  "strat_bull_call_ladder_desc": "Un bull call spread avec un troisième call vendu plus haut. Le crédit supplémentaire ouvre un risque illimité en haut.",
  "strat_bear_call_ladder_desc": "Un call vendu en bas et deux achetés en haut : perd dans le range, gagne sur un fort mouvement haussier.",
