  "calcDescSpot": "Ce que vous recevez réellement en achetant ou vendant au comptant, commissions déduites.",
  "calcDescMeasure": "L'objectif de cours qu'une figure chartiste projette à partir de sa propre hauteur : c'est ainsi qu'on mesure un triangle, une ETE ou un rectangle.",
