  "calcDescMontecarlo": "Comment se répartissent les résultats de votre système si vous rejouez des milliers de fois les mêmes trades dans un ordre différent. Montre la série perdante que vos statistiques autorisent.",
  "calcDescSimulator": "L'évolution du compte par phases, en appliquant vos règles de risque et en voyant quand la taille de position doit monter ou descendre.",
