  "helpAria": "Voir l'explication",
  "helpRiskPerTrade": "Le pourcentage du compte que vous acceptez de perdre SUR CE TRADE, pas au total. L'usage est 1 à 2 % : à 2 %, il faut environ 35 pertes d'affilée pour diviser le compte par deux ; à 10 %, sept suffisent.",
  "helpStopDistance": "C'est la distance entre l'entrée et le stop qui fixe la taille, pas l'inverse. Un stop plus serré permet d'acheter plus d'unités à risque égal, mais il est touché plus souvent.",
  "helpRequiredLeverage": "Le levier nécessaire pour ouvrir cette position avec votre capital. Ce n'est pas une recommandation : s'il ressort élevé, c'est en général que le stop est trop loin pour votre compte, pas qu'il faut s'endetter.",
  "helpAccountBalance": "Utilisez le solde réel d'aujourd'hui, pas celui que vous espérez. Tout le calcul de risque repose sur ce chiffre : l'arrondir à la hausse gonfle toutes vos positions.",
  "helpPipValue": "Ce que la position gagne ou perd quand la paire bouge d'un pip. Cela dépend de la paire et de la devise du compte : un pip d'EURUSD ne vaut pas autant qu'un pip d'USDJPY.",
  "helpLotSize": "Un lot standard vaut 100 000 unités de la devise de base ; un mini 10 000 et un micro 1 000. Un résultat de 0,35 lot signifie 35 000 unités, pas 35.",
  "helpLeverage": "Il multiplie le résultat autant à la hausse qu'à la baisse. À 10x, un mouvement de 10 % contre vous ne vous laisse pas à 90 % : il vous liquide. La liquidation arrive avant la perte totale.",
  "helpContractSize": "Chaque contrat à terme représente une quantité fixe du sous-jacent, différente selon le marché. Un E-mini S&P vaut 50 $ par point ; un contrat de brut, 1 000 barils. C'est ce multiplicateur qui transforme un petit mouvement en gros résultat.",
  "helpSimulations": "Combien de fois vos trades sont remélangés au hasard. Avec peu de tirages, le résultat change à chaque clic ; à partir de 5 000 environ, les percentiles se stabilisent et deviennent fiables.",
  "helpDrawdown": "La plus forte baisse entre un sommet du compte et le creux qui suit. C'est le chiffre qui décide vraiment si vous tiendrez le système : presque personne ne continue à trader une série qu'il n'avait pas anticipée.",
