  "stratWinRateNote": "À propos des taux de réussite de cette page : ce sont des fourchettes INDICATIVES servant habituellement à décrire chaque style, pas des résultats mesurés. Elles ne portent ni échantillon, ni période, ni instrument, ni source, elles ne peuvent donc servir à dimensionner quoi que ce soit. Et même mesurées, elles diraient peu de chose seules : 45 % avec des gains trois fois supérieurs aux pertes rapporte de l'argent, et 70 % avec des pertes trois fois supérieures aux gains en perd. Ce qui décide, c'est l'espérance — réussite × gain moyen − échec × perte moyenne —, pas le pourcentage. La vôtre sort de votre propre journal, pas de ce tableau.",
